def solve(gi, gdo=None):
    h,w=len(gi),len(gi[0]); bg=gi[0][0]
    cells=defaultdict(list)
    for i in range(h):
        for j in range(w):
            if gi[i][j]!=bg: cells[gi[i][j]].append((i,j))
    # corner color: the one whose cells form perfect rect corners (all combos of extremes present)
    corner=None
    for c,ps in cells.items():
        rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if len(ps)==2 and True: pass
        if {(r0,c0),(r0,c1),(r1,c0),(r1,c1)}==set(ps) and len(ps)>=4:
            corner=c; H,W=r1-r0+1,c1-c0+1
    out=[[bg]*W for _ in range(H)]
    cells.pop(corner,None)
    # draw frames
    for r in (0,H-1):
        out[r][0]=corner; out[r][W-1]=corner
    for c in (0,W-1):
        out[0][c]=corner; out[H-1][c]=corner
    # draw remaining shapes with greedy collision-avoidant placement
    order=[]
    while cells:
        best=None
        for c,ps in list(cells.items()):
            rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
            bh,bw=max(rs)-min(rs)+1,max(cs)-min(cs)+1
            for sr in range(H-bh+1):
                for sc in range(W-bw+1):
                    ok=True; hit=False
                    for (r,cc) in [(a,b) for a in range(bh) for b_ in range(bw)]:
                        pass
                    occupied={(rr,cc) for rr in range(sr,sr+bh) for cc in range(sc,sc+bw) if out[rr][cc]!=bg}
                    for (r,cc) in ps:
                        nr,nc=sr+r-min(rs),sc+cc-min(cs)
                        if (nr,nc) in occupied or not(0<=nr<H and 0<=nc<W): ok=False;break
                    if ok and best is None or (ok and (sr,sc)<best[0]):
                        best=(c,tuple(sorted(ps)),tuple(sorted(ps)),(sr,sc)); break
                if best: break
            if best: break
        if best is None: break
        if best is None: return None
        c,ps,dup,(sr,sc)=best
        for (r,cc) in ps:
            out[sr+r-dup[0]][sc+cc-dup[1]]=c
        del cells[c]
    return out

