from collections import defaultdict
def solve(gi):
    h,w=len(gi),len(gi[0]); bg=gi[0][0]
    cells=defaultdict(list)
    for i in range(h):
        for j in range(w):
            if gi[i][j]!=bg: cells[gi[i][j]].append((i,j))
    # corner color: forms perfect rect corners
    corner=None
    for c,ps in cells.items():
        rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if len(ps)==4 and {(r0,c0),(r0,c1),(r1,c0),(r1,c1)}==set(ps):
            corner=c; H,W=r1-r0+1,c1-c0+1
    out=[[bg]*W for _ in range(H)]
    for r in (0,H-1):
        for cc in (0,W-1): out[r][cc]=corner
    others={c:[(r-min(p[0] for p in ps),c2-min(q[1] for q in ps)) for r,c2 in ps] for c,ps in cells.items() if c!=corner}
    occupied={(r,cc) for r in (0,H-1) for cc in (0,W-1)}
    while len(others)>0:
        best=None
        for c,ps in list(others.items()):
            bh=max(r for r,_ in ps)+1; bw=max(cc for _,cc in ps)+1
            for sr in range(H-bh+1):
                for sc in range(W-bw+1):
                    pts={(sr+r,sc+cc) for r,cc in ps}
                    if pts & occupied: continue
                    if best is None or (sr,sc)<best[0]: best=((sr,sc),c,tuple(sorted(ps)))
        if best is None: return None,None,others.copy()
        (sr,sc),c,ps=best
        for r,cc in ps: out[sr+r][sc+cc]=c; occupied.add((sr+r,sc+cc))
        del others[c]
    return out,None,None
